    function ValidateField_hosp_diarias(&$Campos_Crit, &$Campos_Falta, &$Campos_Erros)
    {
        global $teste_validade;
        $hasError = false;
      if (isset($this->Field_no_validate['hosp_diarias'])) {
          if (!empty($this->field_config['hosp_diarias']['symbol_dec'])) {
              $this->sc_remove_currency($this->hosp_diarias, $this->field_config['hosp_diarias']['symbol_dec'], $this->field_config['hosp_diarias']['symbol_grp'], $this->field_config['hosp_diarias']['symbol_mon']); 
              nm_limpa_valor($this->hosp_diarias, $this->field_config['hosp_diarias']['symbol_dec'], $this->field_config['hosp_diarias']['symbol_grp']) ; 
          }
          return;
      }
      if ($this->hosp_diarias === "" || is_null($this->hosp_diarias))  
      { 
          $this->hosp_diarias = 0;
          $this->sc_force_zero[] = 'hosp_diarias';
      } 
      if (!empty($this->field_config['hosp_diarias']['symbol_dec']))
      {
          $this->sc_remove_currency($this->hosp_diarias, $this->field_config['hosp_diarias']['symbol_dec'], $this->field_config['hosp_diarias']['symbol_grp'], $this->field_config['hosp_diarias']['symbol_mon']); 
          nm_limpa_valor($this->hosp_diarias, $this->field_config['hosp_diarias']['symbol_dec'], $this->field_config['hosp_diarias']['symbol_grp']) ; 
          if ('.' == substr($this->hosp_diarias, 0, 1))
          {
              if ('' == str_replace('0', '', substr($this->hosp_diarias, 1)))
              {
                  $this->hosp_diarias = '';
              }
              else
              {
                  $this->hosp_diarias = '0' . $this->hosp_diarias;
              }
          }
      }
      if ($this->nmgp_opcao != "excluir") 
      { 
          if ($this->hosp_diarias != '')  
          { 
              $iTestSize = 13;
              if (strlen($this->hosp_diarias) > $iTestSize)  
              { 
                  $hasError = true;
                  $Campos_Crit .= "Diárias:: " . $this->Ini->Nm_lang['lang_errm_size']; 
                  if (!isset($Campos_Erros['hosp_diarias']))
                  {
                      $Campos_Erros['hosp_diarias'] = array();
                  }
                  $Campos_Erros['hosp_diarias'][] = $this->Ini->Nm_lang['lang_errm_size'];
                  if (!isset($this->NM_ajax_info['errList']['hosp_diarias']) || !is_array($this->NM_ajax_info['errList']['hosp_diarias']))
                  {
                      $this->NM_ajax_info['errList']['hosp_diarias'] = array();
                  }
                  $this->NM_ajax_info['errList']['hosp_diarias'][] = $this->Ini->Nm_lang['lang_errm_size'];
              } 
              if ($teste_validade->Valor($this->hosp_diarias, 10, 2, 0, 0, "N") == false)  
              { 
                  $hasError = true;
                  $Campos_Crit .= "Diárias:; " ; 
                  if (!isset($Campos_Erros['hosp_diarias']))
                  {
                      $Campos_Erros['hosp_diarias'] = array();
                  }
                  $Campos_Erros['hosp_diarias'][] = "" . $this->Ini->Nm_lang['lang_errm_ajax_data'] . "";
                  if (!isset($this->NM_ajax_info['errList']['hosp_diarias']) || !is_array($this->NM_ajax_info['errList']['hosp_diarias']))
                  {
                      $this->NM_ajax_info['errList']['hosp_diarias'] = array();
                  }
                  $this->NM_ajax_info['errList']['hosp_diarias'][] = "" . $this->Ini->Nm_lang['lang_errm_ajax_data'] . "";
              } 
          } 
      } 
        if ($hasError) {
