   function nm_converte_datas($use_null = true, $bForce = false)
   {
      $guarda_format_hora = $this->field_config['hosp_dt_checkin']['date_format'];
      if ($this->hosp_dt_checkin != "")  
      { 
          nm_conv_data($this->hosp_dt_checkin, $this->field_config['hosp_dt_checkin']['date_format']) ; 
          $this->hosp_dt_checkin_hora = "00:00:00:000" ; 
          if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_postgres))
          {
              $this->hosp_dt_checkin_hora = substr($this->hosp_dt_checkin_hora, 0, -4);
          }
          elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_mysql))
          {
              $this->hosp_dt_checkin_hora = substr($this->hosp_dt_checkin_hora, 0, -4);
          }
          elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_access))
          {
              $this->hosp_dt_checkin_hora = substr($this->hosp_dt_checkin_hora, 0, -4);
          }
          elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_oracle))
          {
              $this->hosp_dt_checkin_hora = substr($this->hosp_dt_checkin_hora, 0, -4);
          }
          elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_db2))
          {
              $this->hosp_dt_checkin_hora = substr($this->hosp_dt_checkin_hora, 0, -4);
          }
      } 
      if ($this->hosp_dt_checkin == "" && $use_null)  
      { 
          $this->hosp_dt_checkin = "null" ; 
      } 
      $this->field_config['hosp_dt_checkin']['date_format'] = $guarda_format_hora;
      $guarda_format_hora = $this->field_config['hosp_dt_checkout']['date_format'];
      if ($this->hosp_dt_checkout != "")  
      { 
