          {
              $aLookup[] = array('' => '');
          }
          foreach ($aLookup as $aOption)
          {
              foreach ($aOption as $sValue => $sLabel)
              {

                  if ($this->hosp_pagamentos == $sValue)
                  {
                      $this->_tmp_lookup_hosp_pagamentos = $sLabel;
