          }
          foreach ($aLookupOrig as $aValData)
          {
              if (in_array(key($aValData), $this->NM_ajax_info['fldList']['hosp_pagamentos']['valList']))
              {
                  $aLabelTemp[key($aValData)] = current($aValData);
              }
