   function ajax_return_values_hosp_ativo($bForce = false)
   {
          if ('navigate_form' == $this->NM_ajax_opcao || 'backup_line' == $this->NM_ajax_opcao || (isset($this->nmgp_refresh_fields) && in_array("hosp_ativo", $this->nmgp_refresh_fields)) || $bForce)
          {
              $sTmpValue = NM_charset_to_utf8($this->hosp_ativo);
              $aLookup = array();
              $this->_tmp_lookup_hosp_ativo = $this->hosp_ativo;

$aLookup[] = array(form_hospedagem_rsvp_pack_protect_string('Y') => str_replace('<', '&lt;',form_hospedagem_rsvp_pack_protect_string("Ativo")));
$aLookup[] = array(form_hospedagem_rsvp_pack_protect_string('N') => str_replace('<', '&lt;',form_hospedagem_rsvp_pack_protect_string("Inativo")));
$_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['Lookup_hosp_ativo'][] = 'Y';
$_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['Lookup_hosp_ativo'][] = 'N';
          $aLookupOrig = $aLookup;
          $sSelComp = "name=\"hosp_ativo\"";
          if (isset($this->NM_ajax_info['select_html']['hosp_ativo']) && !empty($this->NM_ajax_info['select_html']['hosp_ativo']))
          {
              $sSelComp = str_replace('{SC_100PERC_CLASS_INPUT}', $this->classes_100perc_fields['input'], $this->NM_ajax_info['select_html']['hosp_ativo']);
          }
          $sLookup = '';
          if (empty($aLookup))
          {
              $aLookup[] = array('' => '');
          }
          foreach ($aLookup as $aOption)
          {
              foreach ($aOption as $sValue => $sLabel)
              {

                  if ($this->hosp_ativo == $sValue)
                  {
                      $this->_tmp_lookup_hosp_ativo = $sLabel;
                  }

                  $sOpt     = ($sValue !== $sLabel) ? $sValue : $sLabel;
                  $sLookup .= "<option value=\"" . $sOpt . "\">" . $sLabel . "</option>";
              }
          }
          $aLookup  = $sLookup;
          $this->NM_ajax_info['fldList']['hosp_ativo'] = array(
                       'row'    => '',
               'type'    => 'select',
               'valList' => array($sTmpValue),
              );
          $aLabel     = array();
          $aLabelTemp = array();
          foreach ($this->NM_ajax_info['fldList']['hosp_ativo']['valList'] as $i => $v)
          {
              $this->NM_ajax_info['fldList']['hosp_ativo']['valList'][$i] = form_hospedagem_rsvp_pack_protect_string($v);
          }
          foreach ($aLookupOrig as $aValData)
          {
              if (in_array(key($aValData), $this->NM_ajax_info['fldList']['hosp_ativo']['valList']))
              {
                  $aLabelTemp[key($aValData)] = current($aValData);
              }
          }
          foreach ($this->NM_ajax_info['fldList']['hosp_ativo']['valList'] as $iIndex => $sValue)
          {
              $aLabel[$iIndex] = (isset($aLabelTemp[$sValue])) ? $aLabelTemp[$sValue] : $sValue;
          }
          $this->NM_ajax_info['fldList']['hosp_ativo']['labList'] = $aLabel;
          }
   }

