   function nm_troca_decimal($sc_parm1, $sc_parm2) 
   { 
      $this->hosp_diarias = str_replace($sc_parm1, $sc_parm2, $this->hosp_diarias); 
      $this->hosp_taxas = str_replace($sc_parm1, $sc_parm2, $this->hosp_taxas); 
      $this->hosp_total = str_replace($sc_parm1, $sc_parm2, $this->hosp_total); 
   } 
   function nm_poe_aspas_decimal() 
   { 
      $this->hosp_diarias = "'" . $this->hosp_diarias . "'";
      $this->hosp_taxas = "'" . $this->hosp_taxas . "'";
      $this->hosp_total = "'" . $this->hosp_total . "'";
   } 
   function nm_tira_aspas_decimal() 
   { 
      $this->hosp_diarias = str_replace("'", "", $this->hosp_diarias); 
      $this->hosp_taxas = str_replace("'", "", $this->hosp_taxas); 
      $this->hosp_total = str_replace("'", "", $this->hosp_total); 
   } 
