function CheckRoom()
{
$_SESSION['scriptcase']['form_hospedagem_rsvp']['contr_erro'] = 'on';
  
	

$sql01 = "
	SELECT    
		hospedagem_id		
	FROM
		hospedagem_rsvp		
	WHERE 
		hosp_id_evento = ".$this->Db->qstr($this->hosp_id_evento )." 
	AND  
		acmq_01 = ".$this->Db->qstr($this->hosp_cpf_participante )." 
";	

 
      $nm_select = $sql01; 
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_select; 
      $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
      $this->rs01 = array();
      if ($SCrx = $this->Db->Execute($nm_select)) 
      { 
          $SCy = 0; 
          $nm_count = $SCrx->FieldCount();
          while (!$SCrx->EOF)
          { 
                 for ($SCx = 0; $SCx < $nm_count; $SCx++)
                 { 
                      $this->rs01[$SCy] [$SCx] = $SCrx->fields[$SCx];
                 }
                 $SCy++; 
                 $SCrx->MoveNext();
          } 
          $SCrx->Close();
      } 
      elseif (isset($GLOBALS["NM_ERRO_IBASE"]) && $GLOBALS["NM_ERRO_IBASE"] != 1)  
      { 
          $this->rs01 = false;
          $this->rs01_erro = $this->Db->ErrorMsg();
      } 
	
if (isset($this->rs01[0][0])) {
	$id_hosp = $this->rs01[0][0];
	if ($id_hosp > $this->hospedagem_id ) {		
		$this->conta_roomlist  = 'SIM';			
		$this->nm_mens_alert[] = 'Existem hspedagens vinculadas, ROOM LIST É POSITIVO'; $this->nm_params_alert[] = array(); if ($this->NM_ajax_flag) { $this->sc_ajax_alert('Existem hspedagens vinculadas, ROOM LIST É POSITIVO'); }} else {
		$this->conta_roomlist  = 'NAO';	
	}	
	return true;
} else {
	$this->conta_roomlist  = 'SIM';			
}	

$sql02 = "
	SELECT    
		hospedagem_id		
	FROM
