function conta_roomlist_onChange()
{
$_SESSION['scriptcase']['form_hospedagem_rsvp']['contr_erro'] = 'on';
  
$original_hosp_acompanhante = $this->hosp_acompanhante;
$this->hosp_acompanhante = str_replace("@?@", ";", $this->hosp_acompanhante);
$original_hosp_part_acomp = $this->hosp_part_acomp;
$this->hosp_part_acomp = str_replace("@?@", ";", $this->hosp_part_acomp);
$original_hosp_id_evento = $this->hosp_id_evento;
$original_hosp_cpf_participante = $this->hosp_cpf_participante;
$original_hospedagem_id = $this->hospedagem_id;
$original_conta_roomlist = $this->conta_roomlist;



if ($this->hosp_tipo_pessoa  == 'P') {
	if ($this->hosp_acompanhante  <> '' || $this->hosp_part_acomp  <> '') {
		$this->CheckRoomp();
	}	
}	


$modificado_hosp_acompanhante = $this->hosp_acompanhante;
$modificado_hosp_part_acomp = $this->hosp_part_acomp;
$modificado_hosp_id_evento = $this->hosp_id_evento;
$modificado_hosp_cpf_participante = $this->hosp_cpf_participante;
$modificado_hospedagem_id = $this->hospedagem_id;
$modificado_conta_roomlist = $this->conta_roomlist;
$this->nm_formatar_campos('hosp_acompanhante', 'hosp_part_acomp', 'hosp_id_evento', 'hosp_cpf_participante', 'hospedagem_id', 'conta_roomlist');
if ($original_hosp_acompanhante !== $modificado_hosp_acompanhante || isset($this->nmgp_cmp_readonly['hosp_acompanhante']) || (isset($bFlagRead_hosp_acompanhante) && $bFlagRead_hosp_acompanhante))
{
    $this->ajax_return_values_hosp_acompanhante(true);
}
if ($original_hosp_part_acomp !== $modificado_hosp_part_acomp || isset($this->nmgp_cmp_readonly['hosp_part_acomp']) || (isset($bFlagRead_hosp_part_acomp) && $bFlagRead_hosp_part_acomp))
{
    $this->ajax_return_values_hosp_part_acomp(true);
}
if ($original_hosp_id_evento !== $modificado_hosp_id_evento || isset($this->nmgp_cmp_readonly['hosp_id_evento']) || (isset($bFlagRead_hosp_id_evento) && $bFlagRead_hosp_id_evento))
{
    $this->ajax_return_values_hosp_id_evento(true);
}
if ($original_hosp_cpf_participante !== $modificado_hosp_cpf_participante || isset($this->nmgp_cmp_readonly['hosp_cpf_participante']) || (isset($bFlagRead_hosp_cpf_participante) && $bFlagRead_hosp_cpf_participante))
{
    $this->ajax_return_values_hosp_cpf_participante(true);
}
if ($original_hospedagem_id !== $modificado_hospedagem_id || isset($this->nmgp_cmp_readonly['hospedagem_id']) || (isset($bFlagRead_hospedagem_id) && $bFlagRead_hospedagem_id))
{
