$original_hosp_late_chkout = $this->hosp_late_chkout;



$valor_nul = '';
$sql="
	SELECT    
		evento_id, hotel_id
	FROM
		eventos_hoteis_rsvp
	WHERE 
		evento_id = ".$this->Db->qstr($this->hosp_id_evento )." 
	AND 
		hotel_id = ".$this->Db->qstr($this->hosp_id_hotel )." 
	ORDER BY 		
		hotel_id"
;				
 
      $nm_select = $sql; 
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_select; 
      $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
      $this->rs = array();
      if ($SCrx = $this->Db->Execute($nm_select)) 
      { 
          $SCy = 0; 
          $nm_count = $SCrx->FieldCount();
          while (!$SCrx->EOF)
          { 
                 for ($SCx = 0; $SCx < $nm_count; $SCx++)
                 { 
                      $this->rs[$SCy] [$SCx] = $SCrx->fields[$SCx];
                 }
                 $SCy++; 
                 $SCrx->MoveNext();
          } 
          $SCrx->Close();
      } 
      elseif (isset($GLOBALS["NM_ERRO_IBASE"]) && $GLOBALS["NM_ERRO_IBASE"] != 1)  
      { 
          $this->rs = false;
          $this->rs_erro = $this->Db->ErrorMsg();
      } 
	
if (!isset($this->rs[0][0])) {			
	$this->nm_mens_alert[] = "Hotel não cadastrado para o Evento!"; $this->nm_params_alert[] = array(); if ($this->NM_ajax_flag) { $this->sc_ajax_alert("Hotel não cadastrado para o Evento!"); }}

if ($this->hosp_tipo_pessoa  == "P") {
	$sqlh="
	SELECT 
