		hosp_part_acomp
	FROM 
		hospedagem_rsvp
	WHERE 
		 hosp_part_acomp <> ".$this->Db->qstr($valor_nul)." 
	AND	
		hosp_id_evento = ".$this->Db->qstr($this->sc_temp_vg_evento_id)."	
	AND
		hosp_id_hotel = ".$this->Db->qstr($this->hosp_id_hotel )."
	AND 
		hosp_cpf_participante = ".$this->Db->qstr($this->sc_temp_vg_cpf)."	
