          $this->rsh_erro = $this->Db->ErrorMsg();
      } 
	
	if ($this->Ini->sc_tem_trans_banco)
{
    $this->Db->CommitTrans();
    $this->Ini->sc_tem_trans_banco = false;
}

	$reg_mestre = sizeof($this->rsh );		
	if ($reg_mestre > 0) {				
		for ($i=0;$i<$reg_mestre;++$i) {	
			$_cpf = $this->rsh[$i][0];  
			$_hosp_participante	= $this->rsh[$i][1];   
			$_achou = strpos($_hosp_participante,$this->hosp_cpf_participante );
			if (strlen(trim($_achou)) > 0) {
				$this->nm_mens_alert[] = 'O Participante já possui uma hospedagem definida para este hotel, Confira!'; $this->nm_params_alert[] = array(); if ($this->NM_ajax_flag) { $this->sc_ajax_alert('O Participante já possui uma hospedagem definida para este hotel, Confira!'); }}				 
		}
	}				
} else {
	$sqlh="
