			$fip_usuario = $_SERVER['HTTP_CLIENT_IP'];
		} elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
			$fip_usuario = $_SERVER['HTTP_X_FORWARDED_FOR'];
		} else {
			$fip_usuario = $_SERVER['REMOTE_ADDR'];
		}		
		return $fip_usuario;
	
$_SESSION['scriptcase']['form_hospedagem_rsvp']['contr_erro'] = 'off';
}


function ProcuraPos($haystack, $needle, $nth) {
$_SESSION['scriptcase']['form_hospedagem_rsvp']['contr_erro'] = 'on';
  
	date_default_timezone_set('America/Sao_Paulo');
	$count = 0;
    $pos = -1;
    do {
        $pos = strpos($haystack, $needle, $pos + 1);
        $count++;
    } while ($pos !== false && $count < $nth);
    return $pos;

$_SESSION['scriptcase']['form_hospedagem_rsvp']['contr_erro'] = 'off';
}


