   function Form_lookup_hosp_ativo()
   {
       $nmgp_def_dados  = "";
       $nmgp_def_dados .= "Ativo?#?Y?#?S?@?";
       $nmgp_def_dados .= "Inativo?#?N?#?N?@?";
       $todo = explode("?@?", $nmgp_def_dados);
       return $todo;

   }
