   function SC_lookup_hosp_acompanhante($condicao, $campo)
   {
       $result = array();
       $campo_orig = $campo;
       $campo  = substr($this->Db->qstr($campo), 1, -1);
      if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_sybase))
      { 
          $nm_comando = "SELECT part_nome, part_nome + '  CPF:  ' + part_cpf + '  RG:  ' + part_rg + '   Passaporte:   ' + part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_mysql))
      { 
          $nm_comando = "SELECT part_nome, concat(part_nome,'  CPF:  ',part_cpf,'  RG:  ',part_rg,'   Passaporte:   ',part_passaporte) FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_access))
      { 
          $nm_comando = "SELECT part_nome, part_nome&'  CPF:  '&part_cpf&'  RG:  '&part_rg&'   Passaporte:   '&part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_postgres))
      { 
          $nm_comando = "SELECT part_nome, part_nome||'  CPF:  '||part_cpf||'  RG:  '||part_rg||'   Passaporte:   '||part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_mssql))
      { 
          $nm_comando = "SELECT part_nome, part_nome + '  CPF:  ' + part_cpf + '  RG:  ' + part_rg + '   Passaporte:   ' + part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      elseif (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_db2))
      { 
          $nm_comando = "SELECT part_nome, part_nome||'  CPF:  '||part_cpf||'  RG:  '||part_rg||'   Passaporte:   '||part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
      else 
      { 
          $nm_comando = "SELECT part_nome, part_nome||'  CPF:  '||part_cpf||'  RG:  '||part_rg||'   Passaporte:   '||part_passaporte FROM acompanhantes_rsvp WHERE (#cmp_ipart_nome#cmp_f#cmp_apos LIKE '%#arg_i" . $campo . "#arg_f%'#arg_apos) AND (part_id_evento = '" . $_SESSION['vg_evento_id'] . "') AND (part_ativo = 'Y') AND (part_substituido = 'N') AND (part_cpf <> '" . $_SESSION['vg_cpf'] . "')" ; 
      } 
       if ($condicao == "ii")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "LIKE '#arg_i" . $campo . "#arg_f%'", $nm_comando);
       }
       if ($condicao == "np")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "NOT LIKE '%#arg_i" . $campo . "#arg_f%'", $nm_comando);
       }
       if ($condicao == "df")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "<> '#arg_i" . $campo . "#arg_f'", $nm_comando);
       }
       if ($condicao == "gt")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "> '#arg_i" . $campo . "#arg_f'", $nm_comando);
       }
       if ($condicao == "ge")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", ">= '#arg_i" . $campo . "#arg_f'", $nm_comando);
       }
       if ($condicao == "lt")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "< '#arg_i" . $campo . "#arg_f'", $nm_comando);
       }
       if ($condicao == "le")
       {
           $nm_comando = str_replace("LIKE '%#arg_i" . $campo . "#arg_f%'", "<= '#arg_i" . $campo . "#arg_f'", $nm_comando);
       }
       if (in_array(strtolower($this->Ini->nm_tpbanco), $this->Ini->nm_bases_access))
       {
           $nm_comando = str_replace("#lowerI#", "UCase(", $nm_comando);
       }
       else
       {
           $nm_comando = str_replace("#lowerI#", "Upper(", $nm_comando);
       }
       $nm_comando = str_replace(array('#cmp_i','#cmp_f','#cmp_apos','#arg_i','#arg_f','#arg_apos'), array('','','','','',''), $nm_comando); 
       $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_comando; 
       $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
       if ($rx = $this->Db->Execute($nm_comando)) 
       { 
           $campo = $campo_orig;
           if ($this->NM_case_insensitive)
           {
               $campo  = sc_strtoupper($campo);
           }
           while (!$rx->EOF) 
           { 
               $chave = $rx->fields[1];
               $label = $rx->fields[0];
               if ($this->NM_case_insensitive)
               {
                   $label  = sc_strtoupper($label);
               }
               if ($condicao == "eq" && $campo == $label)
               {
                   $result[] = $chave;
               }
               if ($condicao == "ii" && $campo == substr($label, 0, strlen($campo)))
               {
                   $result[] = $chave;
               }
               if ($condicao == "qp" && strstr($label, $campo))
               {
                   $result[] = $chave;
               }
               if ($condicao == "np" && !strstr($label, $campo))
               {
                   $result[] = $chave;
               }
               if ($condicao == "df" && $campo != $label)
               {
                   $result[] = $chave;
               }
               if ($condicao == "gt" && $label > $campo )
               {
                   $result[] = $chave;
               }
               if ($condicao == "ge" && $label >= $campo)
               {
                   $result[] = $chave;
               }
               if ($condicao == "lt" && $label < $campo)
               {
                   $result[] = $chave;
               }
               if ($condicao == "le" && $label <= $campo)
               {
                   $result[] = $chave;
               }
               $rx->MoveNext() ;
           }  
           return $result;
       }  
       elseif ($GLOBALS["NM_ERRO_IBASE"] != 1)  
       { 
           $this->Erro->mensagem(__FILE__, __LINE__, "banco", $this->Ini->Nm_lang['lang_errm_dber'], $this->Db->ErrorMsg()); 
           exit; 
       } 
   }
