           {
               $tmp_parms .= $val;
           }
           $tmp_parms .= "?@?";
       }
       $nm_apl_parms = $tmp_parms;
   }
   if (empty($opc))
   {
       $_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['opcao'] = "";
       $_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['opc_ant'] = "";
