    function scGetColumnOrderRule($fieldName, &$orderColName, &$orderColOrient, &$orderColRule)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['ordem_cmp'] == $fieldName) {
            $orderColName = $fieldName;
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_hospedagem_rsvp']['ordem_ord'] == " desc") {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_desc;
                $orderColRule = $sortRule = 'desc';
            } else {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_asc;
                $orderColRule = $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule)
    {        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "hospedagem_id":
                return true;
            case "hosp_id_evento":
                return true;
            case "hosp_diarias":
                return true;
            case "hosp_taxas":
                return true;
            case "hosp_total":
                return true;
            case "hosp_id_usuario":
                return true;
            case "hosp_id_participante":
                return true;
            case "id_bloqueio_hotel":
                return true;
            default:
                return false;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "hosp_dt_checkin":
                return 'desc';
            case "hosp_dt_checkout":
                return 'desc';
            case "hosp_hr_checkin":
                return 'desc';
            case "hosp_hr_checkout":
                return 'desc';
            case "hospedagem_id":
                return 'desc';
            case "hosp_id_evento":
                return 'desc';
            case "hosp_cpf_participante":
                return 'desc';
            case "hosp_id_hotel":
                return 'desc';
            case "hosp_acomodacao":
                return 'desc';
            case "hosp_categoria":
                return 'desc';
            case "hosp_pagamentos":
                return 'desc';
            case "hosp_diarias":
                return 'desc';
            case "hosp_taxas":
                return 'desc';
            case "hosp_total":
                return 'desc';
            case "hosp_id_usuario":
                return 'desc';
            case "hosp_alteracao":
                return 'desc';
            case "hosp_id_participante":
                return 'desc';
            case "id_bloqueio_hotel":
                return 'desc';
            default:
                return 'asc';
        }
        return 'asc';
    }

